def PositiveLowerOne (C : ℝ) : Prop :=
  0 ≤ C ∧ ∀ (n : ℕ) (x : Fin n → E), (∀ i, 0 ≤ x i) →
    ∑ i, ‖x i‖ ≤ C * ‖∑ i, x i‖

